fn main() {
    // Listing the app's commands makes each one need a permission
    // (permissions/autogenerated). The bundled pages get theirs from
    // capabilities/; an instance's page only ever gets allow-open-switcher, at
    // run time (src/lib.rs, allow_server).
    tauri_build::try_build(tauri_build::Attributes::new().app_manifest(
        tauri_build::AppManifest::new().commands(&[
            "list_instances",
            "add_instance",
            "switch_instance",
            "remove_instance",
            "rename_instance",
            "open_switcher",
        ]),
    ))
    .expect("failed to run the Tauri build script");
}
